import { getWebSocketUrl as getWebSocketUrlFromConfig } from '@/config/environment.config';
import { checkIsVisitorRoute } from '@/functions/check-is-visitor-route';
import { isUnauthenticatedProxyApiUrl } from '@/lib/api/is-unauthenticated-proxy-api-path';
import axios, { AxiosError, InternalAxiosRequestConfig } from 'axios';
import { getTenantFromUrl } from './getHostFromUrl';

interface DirectApiRequestConfig extends InternalAxiosRequestConfig {
    __retryAfterRefresh?: boolean;
}

const TOKEN_CACHE_TTL_MS = 5000;
const EMPTY_TOKEN_CACHE_TTL_MS = 1000;

let cachedToken: string | null = null;
let cachedTokenExpiresAt = 0;
let inflightTokenRequest: Promise<string | null> | null = null;

/** Rotas de API acessíveis sem sessão (público + render PDF interno). */
function isPublicApiRequestUrl(url?: string): boolean {
    return isUnauthenticatedProxyApiUrl(url);
}

function isPublicAppPathname(pathname: string): boolean {
    return (
        pathname.startsWith('/publico/') || pathname.startsWith('/internal/proposta-digital')
    );
}

/** Páginas de fluxo de auth sem sessão — não precisam consultar o cookie no servidor (evita vários 401 no log). */
function shouldSkipVerificationTokenFetch(pathname: string): boolean {
    if (pathname === '/auth/signin') return true;
    if (pathname === '/auth/signup' || pathname.startsWith('/auth/signup/')) return true;
    if (pathname === '/auth/two-step-verification') return true;
    if (checkIsVisitorRoute(pathname)) return true;
    if (isPublicAppPathname(pathname)) return true;
    return false;
}

/**
 * Obtém a URL da API baseada no ambiente (client-side)
 * Usa variáveis NEXT_PUBLIC_* que são disponíveis no browser
 */
const getDirectApiUrl = (): string => {
    const appEnv = process.env.NEXT_PUBLIC_APP_ENV;

    const isHomol = appEnv === 'homol' || appEnv === 'homologation' || appEnv === 'staging';
    const isProduction = appEnv === 'production' || appEnv === 'prod';

    if (isHomol) {
        const homolUrl = process.env.NEXT_PUBLIC_HOMOL_API_URL || process.env.NEXT_PUBLIC_HOMOL_URL;
        if (homolUrl) return homolUrl;
    }

    if (isProduction) {
        const prodUrl = process.env.NEXT_PUBLIC_PROD_API_URL;
        if (prodUrl) return prodUrl;
    }

    return process.env.NEXT_PUBLIC_DEV_API_URL || 'http://127.0.0.1:8000';
};

/**
 * Fetches the Bearer token from httpOnly cookies via the Next route.
 * With forceRefresh: skips the client TTL cache and hits the server again so
 * verification-token can rotate the access JWT (and Set-Cookie) when needed.
 */
export const getTokenViaAPI = async (
    { forceRefresh = false }: { forceRefresh?: boolean } = {},
): Promise<string | null> => {
    if (typeof window === 'undefined') {
        try {
            const [{ cookies }, { getSessionTokensFromCookies }] = await Promise.all([
                import('next/headers'),
                import('@/lib/auth/auth-cookies'),
            ]);
            return getSessionTokensFromCookies(await cookies()).access;
        } catch {
            return null;
        }
    }

    const now = Date.now();

    if (!forceRefresh && cachedTokenExpiresAt > now) {
        return cachedToken;
    }

    if (
        typeof window !== 'undefined' &&
        !forceRefresh &&
        shouldSkipVerificationTokenFetch(window.location.pathname)
    ) {
        cachedToken = null;
        cachedTokenExpiresAt = Date.now() + EMPTY_TOKEN_CACHE_TTL_MS;
        return null;
    }

    if (!forceRefresh && inflightTokenRequest) {
        return inflightTokenRequest;
    }

